(function(root){
  'use strict';
  const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
  const copy=x=>JSON.parse(JSON.stringify(x));
  const fail=m=>{throw new Error(m)};
  const object=(v,label)=>{if(!v||typeof v!=='object'||Array.isArray(v))fail(label+': ожидается объект');return v};
  const list=(v,label,max)=>{if(!Array.isArray(v)||v.length>max)fail(label+': недопустимый список');return v};
  const num=(v,label,min,max,integer=false)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||(integer&&!Number.isInteger(v)))fail(label+': недопустимое число');return v};
  const text=(v,label)=>{if(typeof v!=='string'||!v.trim()||v.trim().length>100)fail(label+': недопустимое название');return v.trim()};
  function date(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v+'T12:00:00Z'))||new Date(v+'T12:00:00Z').toISOString().slice(0,10)!==v)fail('Неверная календарная дата');return v}
  function numbers(s){object(s,'Подход');return {weight:num(s.weight,'Вес',0.5,200),reps:num(s.reps,'Повторы',1,1000,true),bells:s.bells===undefined?1:num(s.bells,'Количество гирь',1,2,true)}}
  function program(p){return list(p,'Программа',30).map(e=>{object(e,'Упражнение');return {name:text(e.name,'Упражнение'),sets:num(e.sets,'Число подходов',1,20,true),...numbers(e)}})}
  function exercises(p,counter){return list(p,'Упражнения тренировки',30).map(e=>{object(e,'Упражнение');return {name:text(e.name,'Упражнение'),sets:list(e.sets,'Подходы',100).map(s=>{if(++counter.n>100000)fail('В копии более 100 000 подходов');if(typeof s.done!=='boolean')fail('У подхода отсутствует отметка выполнения');const row={...numbers(s),done:s.done};if(own(s,'plan'))row.plan=s.plan===null?null:numbers(s.plan);if(s.effort!==undefined)row.effort=s.effort===null?null:num(s.effort,'Сложность',1,10,true);return row})}})}
  function normalize(raw){
    object(raw,'Резервная копия');
    if(raw.format!==undefined){if(raw.format!=='girya-local-backup'||raw.schema_version!==1||raw.storage_format!=='girya-v1')fail('Формат или версия копии пока не поддерживаются');raw=object(raw.data,'Данные копии')}
    if(!own(raw,'sessions')||!own(raw,'measurements')||!own(raw,'drafts')||(!own(raw,'program')&&!own(raw,'programs')))fail('Это не полная резервная копия. Для программы используй импорт в разделе «Моя программа».');
    const out={programs:{},activeProgram:['A','B','C'].includes(raw.activeProgram)?raw.activeProgram:'A',sessions:[],measurements:[],drafts:{},draftPrograms:{}};
    if(raw.programs!==undefined){object(raw.programs,'Программы');for(const k of ['A','B','C'])if(own(raw.programs,k))out.programs[k]=program(raw.programs[k])}
    else out.programs.A=program(raw.program);
    if(!Object.keys(out.programs).length||Object.values(out.programs).some(p=>!p.length))fail('В копии нет заполненной программы');
    const counter={n:0},dates=new Set();
    out.sessions=list(raw.sessions,'История',10000).map(s=>{object(s,'Тренировка');const d=date(s.date);if(dates.has(d))fail('В копии несколько тренировок одной даты: текущая версия не умеет объединять их автоматически');dates.add(d);const row={date:d,exercises:exercises(s.exercises,counter)};if(s.minutes!==undefined)row.minutes=num(s.minutes,'Длительность',0,1000000);if(s.programKey!==undefined)row.programKey=s.programKey===null?null:(['A','B','C'].includes(s.programKey)?s.programKey:fail('Неизвестная программа тренировки'));return row});
    object(raw.drafts,'Черновики');if(Object.keys(raw.drafts).length>10000)fail('Слишком много черновиков');for(const [d,ex] of Object.entries(raw.drafts))out.drafts[date(d)]=exercises(ex,counter);
    const dp=raw.draftPrograms===undefined?{}:object(raw.draftPrograms,'Программы черновиков');for(const [d,key] of Object.entries(dp)){date(d);if(!['A','B','C'].includes(key))fail('Неизвестная программа черновика');if(own(out.drafts,d))out.draftPrograms[d]=key}
    const md=new Set();out.measurements=list(raw.measurements,'Замеры',10000).map(m=>{object(m,'Замер');const d=date(m.date);if(md.has(d))fail('Повторная дата замеров в файле');md.add(d);const row={date:d};for(const key of ['weight','chest','waist','hips','arm','thigh']){const value=m[key];if(value===undefined||value===''||value===null)continue;if(typeof value!=='number'&&typeof value!=='string')fail('Неверный замер');row[key]=num(Number(value),'Замер '+key,1,500)}return row});
    return out;
  }
  function canonical(v){if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v)}
  function days(data){const result=new Map();for(const s of data.sessions)result.set(s.date,{session:s});for(const [d,ex] of Object.entries(data.drafts)){const row=result.get(d)||{};row.draft=ex;if(data.draftPrograms[d])row.programKey=data.draftPrograms[d];result.set(d,row)}return result}
  function describeDay(row){return `${row.session?'сохранённая тренировка':'без завершённой тренировки'}${row.draft?', есть черновик':''}`}
  function preview(currentRaw,incomingRaw){const current=normalize(currentRaw),incoming=normalize(incomingRaw),entries=[];const push=(type,key,a,b)=>entries.push({id:type+':'+key,type,key,state:a===undefined?'new':canonical(a)===canonical(b)?'same':'conflict',current:a,incoming:b});for(const [k,v] of Object.entries(incoming.programs))push('program',k,current.programs[k],v);const cd=days(current);for(const [d,v] of days(incoming))push('day',d,cd.get(d),v);const cm=new Map(current.measurements.map(m=>[m.date,m]));for(const m of incoming.measurements)push('measurement',m.date,cm.get(m.date),m);return {current,incoming,entries,summary:{sessions:incoming.sessions.length,drafts:Object.keys(incoming.drafts).length,measurements:incoming.measurements.length,programs:Object.keys(incoming.programs).length,new:entries.filter(e=>e.state==='new').length,same:entries.filter(e=>e.state==='same').length,conflicts:entries.filter(e=>e.state==='conflict').length}}}
  function merge(model,choices={}){const out=copy(model.current),dayMap=days(out),mm=new Map(out.measurements.map(m=>[m.date,m]));let changed=0;for(const e of model.entries){if(e.state==='same'||(e.state==='conflict'&&choices[e.id]!=='import'))continue;changed++;if(e.type==='program')out.programs[e.key]=copy(e.incoming);if(e.type==='day')dayMap.set(e.key,copy(e.incoming));if(e.type==='measurement')mm.set(e.key,copy(e.incoming))}out.sessions=[];out.drafts={};out.draftPrograms={};for(const [d,row] of [...dayMap].sort(([a],[b])=>a.localeCompare(b))){if(row.session)out.sessions.push(row.session);if(row.draft){out.drafts[d]=row.draft;if(row.programKey)out.draftPrograms[d]=row.programKey}}out.measurements=[...mm.values()].sort((a,b)=>a.date.localeCompare(b.date));out.program=out.programs[out.activeProgram]||out.programs.A;return {data:out,changed}}
  function envelope(data,installationId){return {format:'girya-local-backup',schema_version:1,storage_format:'girya-v1',source_installation_id:installationId,exported_at:new Date().toISOString(),data:copy(data)}}
  async function checksum(data){const bytes=new TextEncoder().encode(canonical(data));const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')} async function verifyIntegrity(raw){if(raw.integrity===undefined)return;if(raw.integrity?.algorithm!=='SHA-256'||typeof raw.integrity.digest!=='string'||raw.integrity.digest!==await checksum(raw.data))fail('Контрольная сумма не совпала: файл повреждён или изменён')} const api={normalize,canonical,preview,merge,envelope,describeDay,checksum,verifyIntegrity};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.GiryaBackup=api;
})(typeof globalThis!=='undefined'?globalThis:this);


